// The checklist for a headline and excerpt, and whether facts were checked.
function checklist(title, excerpt, facts) {
	const headline = String(title || '').trim();
	const summary = String(excerpt || '').trim();
	const letters = headline.replace(/[^A-Za-zÀ-ɏ]/g, '');
	return [
		{ label: 'Headline is 20 to 70 characters', ok: headline.length >= 20 && headline.length <= 70, now: headline.length },
		{ label: 'Headline is not in capitals', ok: !(letters.length >= 4 && letters === letters.toUpperCase()) },
		{ label: 'Excerpt of at least 50 characters', ok: summary.length >= 50, now: summary.length },
		{ label: 'Facts and names checked', ok: facts === true },
	];
}

// The fields, the checklist as they read now, and the buttons that fit.
function draw(posts, state) {
	const post = posts[0];
	if (!post) {
		return { type: 'text', children: 'Save the post to see its checklist.' };
	}
	const title = state.title === null ? post.title : state.title;
	const excerpt = state.excerpt === null ? post.excerpt : state.excerpt;
	const items = checklist(title, excerpt, state.facts);
	const ready = items.every((item) => item.ok);
	const changed = title !== post.title || excerpt !== post.excerpt;
	const buttons = [];
	if (changed) {
		buttons.push({ type: 'button', props: { id: 'save', label: 'Save', variant: 'secondary', onClick: { $use: 'save', row: post.id } } });
	}
	if (ready && !changed && post.status !== 'publish') {
		buttons.push({ type: 'button', props: { id: 'publish', label: 'Publish', variant: 'primary', onClick: { $use: 'publish', row: post.id } } });
	}
	return {
		type: 'stack',
		props: { gap: 3 },
		children: [
			{ type: 'text-input', props: { id: 'title', label: 'Headline', value: post.title, onChange: { $event: 'title' } } },
			{ type: 'textarea', props: { id: 'excerpt', label: 'Excerpt', value: post.excerpt, rows: 3, onChange: { $event: 'excerpt' } } },
			{ type: 'checkbox', props: { id: 'facts', label: 'Facts and names checked', value: false, onChange: { $event: 'facts' } } },
			{
				type: 'stack',
				props: { gap: 1 },
				children: items.map((item) => ({
					type: 'text',
					props: { variant: item.ok ? 'body' : 'strong' },
					children: `${item.ok ? '✓' : '✗'} ${item.label}${!item.ok && typeof item.now === 'number' ? ` (${item.now} now)` : ''}`,
				})),
			},
			changed && ready ? { type: 'text', props: { variant: 'muted' }, children: 'Save your changes before publishing.' } : null,
			buttons.length ? { type: 'stack', props: { direction: 'row', gap: 2 }, children: buttons } : null,
		].filter(Boolean),
	};
}

// What the writer typed or ticked.
function edit(state, event, value) {
	if (event === 'title' || event === 'excerpt') {
		return { ...state, [event]: String(value) };
	}
	if (event === 'facts') {
		return { ...state, facts: value === true };
	}
	return state;
}
